import src_default from "./index.mjs";
//#region src/astro.ts
function astro_default(options) {
	return {
		name: "unplugin-fonts",
		hooks: { "astro:config:setup": async (astro) => {
			if (options?.custom) options.custom.stripPrefix = "public/";
			astro.config.vite.plugins ||= [];
			astro.config.vite.plugins.push(src_default.vite(options));
			astro.injectScript("page-ssr", "import \"unfonts.css\";");
		} }
	};
}
//#endregion
export { astro_default as default };
